namespace AI103.ChatApp.Domain.Entities;

/// <summary>
/// Application-owned conversation. <see cref="Id"/> is generated by this app and is NOT the
/// model provider's response ID. <see cref="LatestResponseId"/> is the provider's ID of the last
/// response, and is what gets sent as <c>previous_response_id</c> on the next turn.
/// </summary>
public sealed class Conversation
{
    private readonly object _gate = new();
    private readonly List<ChatMessage> _messages = [];

    public Conversation()
    {
        Id = Guid.NewGuid().ToString("N");
        CreatedAtUtc = DateTimeOffset.UtcNow;
    }

    public string Id { get; }

    public DateTimeOffset CreatedAtUtc { get; }

    public string? LatestResponseId { get; private set; }

    /// <summary>A snapshot, so callers can enumerate while another request appends.</summary>
    public IReadOnlyList<ChatMessage> Messages
    {
        get
        {
            lock (_gate)
            {
                return _messages.ToArray();
            }
        }
    }

    public void AddMessage(ChatMessage message)
    {
        ArgumentNullException.ThrowIfNull(message);
        lock (_gate)
        {
            _messages.Add(message);
        }
    }

    public void RecordResponseId(string responseId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(responseId);
        lock (_gate)
        {
            LatestResponseId = responseId;
        }
    }

    /// <summary>
    /// Records a finished turn atomically: the user's prompt, the model's answer and the new response ID.
    /// </summary>
    public void RecordTurn(ChatMessage userMessage, ChatMessage assistantMessage, string responseId)
    {
        ArgumentNullException.ThrowIfNull(userMessage);
        ArgumentNullException.ThrowIfNull(assistantMessage);
        ArgumentException.ThrowIfNullOrWhiteSpace(responseId);
        lock (_gate)
        {
            _messages.Add(userMessage);
            _messages.Add(assistantMessage);
            LatestResponseId = responseId;
        }
    }
}
